function financeCheck(bool $ok, string $label): void
{
    global $checks;
    if (!$ok)throw new RuntimeException('Assertion failed: '.$label);
    $checks++;
    echo "[pass] $label\n";
}
function financeReject(callable $call, string $label): void
{
    try {
        $call();
    } catch (core\exception\CommonException $e) {
        financeCheck(true, $label);
        return;
    }throw new RuntimeException('Not rejected: '.$label);
